// ==============================================================================
// Multi-Client Registry & Lead Normalization
// Secrets are loaded exclusively from environment variables ($env)
// ==============================================================================
const results = [];

for (const item of $input.all()) {
  const payload = item.json.body || {};
  const query = item.json.query || {};
  const record = payload.record || {};

  const clientId = query.client_id || 'client_1';

  // Multi-Client Directory (API keys injected via n8n environment variables)
  const clientRegistry = {
    client_1: {
      clientName: 'Kynd Studio',
      twentyGraphqlUrl: $env.TWENTY_GRAPHQL_URL_CLIENT_1 || $env.TWENTY_GRAPHQL_URL || 'http://server:3000/graphql',
      twentyApiKey: $env.TWENTY_API_KEY_CLIENT_1 || $env.TWENTY_API_KEY || '',
      brandVoicePrompt: 'Warm, consultative, design-led, and highly professional.',
      outboundSenderEmail: $env.OUTBOUND_SENDER_EMAIL_CLIENT_1 || 'hello@waqas.pro',
      outboundSenderName: $env.OUTBOUND_SENDER_NAME_CLIENT_1 || 'Kynd Studio Team'
    },
    client_2: {
      clientName: 'Client Two Workspace',
      twentyGraphqlUrl: $env.TWENTY_GRAPHQL_URL_CLIENT_2 || $env.TWENTY_GRAPHQL_URL || 'http://server:3000/graphql',
      twentyApiKey: $env.TWENTY_API_KEY_CLIENT_2 || $env.TWENTY_API_KEY || '',
      brandVoicePrompt: 'Energetic, fast-paced, direct, and ROI-focused.',
      outboundSenderEmail: $env.OUTBOUND_SENDER_EMAIL_CLIENT_2 || 'sales@clienttwo.com',
      outboundSenderName: $env.OUTBOUND_SENDER_NAME_CLIENT_2 || 'Client Two Sales'
    }
  };

  const clientConfig = clientRegistry[clientId] || clientRegistry.client_1;

  if (!clientConfig.twentyApiKey) {
    throw new Error(`Missing Twenty CRM API key environment variable for client '${clientId}'. Set TWENTY_API_KEY_CLIENT_1 / TWENTY_API_KEY in n8n.`);
  }

  // Normalize Lead Details
  const firstName = record.name?.firstName || '';
  const lastName = record.name?.lastName || '';
  const fullName = (firstName + ' ' + lastName).trim() || 'Valued Contact';
  const primaryEmail = record.emails?.primaryEmail || record.email || '';
  const primaryPhone = record.phones?.primaryPhoneNumber || record.phone || '';
  const companyName = record.company?.name || record.companyName || 'your organization';
  const jobTitle = record.jobTitle || 'Decision Maker';
  const source = record.source || 'Website Inbound';

  if (!record.id || !primaryEmail) {
    continue;
  }

  results.push({
    json: {
      clientId,
      clientConfig,
      lead: {
        id: record.id,
        firstName,
        lastName,
        fullName,
        primaryEmail,
        primaryPhone,
        companyName,
        jobTitle,
        source,
        aiFollowupStatus: record.aiFollowupStatus || 'PENDING'
      }
    }
  });
}

return results;

