// Parse AI response and merge with current item lead context
const rawAi = $input.item.json.choices?.[0]?.message?.content || '{}';
const promptContext = $('Format AI Qualification Prompt').item.json;
const lead = promptContext.lead;
const clientConfig = promptContext.clientConfig;

let aiParsed = {};
try {
  aiParsed = JSON.parse(rawAi);
} catch (e) {
  aiParsed = {
    leadScore: 7,
    intentCategory: 'Medium',
    qualificationSummary: 'Auto-qualified inbound contact',
    emailSubject: 'Excited to connect with ' + lead.companyName,
    emailBodyText: 'Hello ' + (lead.firstName || lead.fullName) + ', thank you for reaching out to us!',
    emailBodyHtml: '<p>Hello ' + (lead.firstName || lead.fullName) + ',</p><p>Thank you for reaching out to us!</p>'
  };
}

// Generate unique UUID for note
const noteId = (typeof crypto !== 'undefined' && crypto.randomUUID)
  ? crypto.randomUUID()
  : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
      const r = Math.random() * 16 | 0;
      const v = c === 'x' ? r : (r & 0x3 | 0x8);
      return v.toString(16);
    });

return [{
  json: {
    lead,
    clientConfig,
    aiResult: aiParsed,
    noteId
  }
}];

